INSERT IGNORE INTO review_repo_catalog (full_name, name, description, stars, created_at) VALUES
('zhijiantianya/ruoyi-vue-pro', 'ruoyi-vue-pro', '🔥 官方推荐  🔥 RuoYi-Vue 全新 Pro 版本，优化重构所有功能。基于 Spring Boot + MyBatis Plus + Vue & Element 实现的后台管理系统 + 微信小程序，支持 RBAC动态权限、数据权', 111645, NOW()),
